class RubySdk
  module Codegen
    # An empty module whose client-facing schema is core's: the engine serves
    # that schema only for a module. A directory source loads every file.
    module StandIn
      NAME = "core-schema".freeze

      MANIFEST = <<~TOML.freeze
        name = "core-schema"

        [entrypoint]
        kind = "dang"
        source = "./sdk/entrypoint"
      TOML

      TYPES = <<~DANG.freeze
        # Code generated by dagger. DO NOT EDIT.

        type ModuleTypes {
          pub all: [TypeDef!]! {
            [
              typeDef.withObject("CoreSchema")
                .withConstructor(
                  function("", typeDef.withObject("CoreSchema"))
                ),
            ]
          }
        }
      DANG

      MAIN = <<~DANG.freeze
        type Entrypoint implements ModuleEntrypoint {
          pub types(workspace: Workspace!): [TypeDef!]! {
            ModuleTypes().all
          }

          pub call(
            workspace: Workspace!,
            receiverType: String!,
            receiverValue: JSON,
            fnName: String!,
            fnArgs: JSON!,
          ): JSON! {
            raise "the core schema stand-in has no function"
          }
        }
      DANG

      FILES = {
        "dagger-module.toml" => MANIFEST,
        "sdk/entrypoint/types.dang" => TYPES,
        "sdk/entrypoint/main.dang" => MAIN
      }.freeze
    end
  end
end
